-- Read-only diagnostics for 90 release templates with displayId=0,
-- where original Legion SQL has a nonzero model. Not all zero models are bugs.
-- Run on the world database after updates; do not alter any data here.
SELECT t.entry,t.type,t.displayId,t.name,t.AIName,t.ScriptName,
       (SELECT COUNT(*) FROM gameobject g WHERE g.id=t.entry) AS current_spawns
FROM gameobject_template t
WHERE t.entry IN (245102,245234,245794,245924,245994,246148,246518,246984,247037,247038,247052,248475,248575,248781,248782,248876,248908,249744,249748,250220,250221,250222,250223,250224,250225,250226,250227,250228,250229,250230,250231,250232,250233,250234,250295,250364,250367,250650,251262,251504,251615,251696,251697,251698,252017,252045,252049,252241,252243,252244,252796,252800,260004,266081,266166,266291,266307,266588,266594,266595,266732,266734,266886,267003,267041,267176,267177,267180,267222,267227,267353,267492,267641,267952,268359,268377,268378,268379,268408,268448,268454,268458,268474,268475,268476,268477,268479,268617,268626,268736) AND t.displayId=0
ORDER BY t.entry;
